'use strict'
/**
 * dsh-skill-hub — demo host half.
 *
 * A deliberately minimal build of the same package, small enough that the whole
 * built payload can be read back and re-submitted without truncation. Full
 * commentary, repository diagnostics and the polling scan live in
 * `src/host/host.js`; this file keeps only what the switches themselves need.
 *
 * This is the copy the running `skhub-1/pkg-2` Package was built from, so it
 * carries the two fixes that package needed:
 *
 *   1. `parse()` used to leave `whenToUse` off the definition it returned, so
 *      the first catalog row carried `whenToUse: undefined` and the panel RPC
 *      rejected the whole response ("must be lossless JSON"). The field is now
 *      always a string.
 *   2. the row count travels as `offCount: off.size` rather than as an array
 *      converted from the Set on every call.
 */

/** The shared skill repository every agent on this machine reads. */
const REPO = 'C:\\Users\\17196\\.agents\\skills'

/** Kebab-case, exactly as the registry validates skill names. */
const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

const inject = ['skills', 'timer']

/**
 * @param {object} ctx - the guarded Cordis context a host half receives.
 */
function apply(ctx) {
  const skills = ctx.skills
  const fs = ctx.get('fs')
  const off = new Set()
  const meta = new Map()
  let defs = []
  let sig
  let pending
  let poke = function () {}

  const str = function (value) { return typeof value === 'string' ? value : '' }

  const unquote = function (value) {
    const s = str(value).trim()
    if (s.length >= 2) {
      const a = s.charAt(0)
      const b = s.charAt(s.length - 1)
      if ((a === '"' && b === '"') || (a === "'" && b === "'")) return s.slice(1, s.length - 1)
    }
    return s
  }

  /** Record what the panel needs about a skill, with every field a string. */
  const remember = function (name, description, whenToUse) {
    meta.set(str(name), { description: str(description), whenToUse: str(whenToUse) })
  }

  /*** A flat `key: value` frontmatter reader; null means DSH would refuse it too. */
  const parse = function (raw) {
    let s = raw
    if (s.charCodeAt(0) === 0xfeff) s = s.slice(1)
    if (s.slice(0, 3) !== '---') return null
    const brk = s.indexOf('\n')
    if (brk < 0) return null
    const lines = s.slice(brk + 1).split('\n')
    const data = {}
    const body = []
    let shut = false
    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i].replace(/\r$/, '')
      if (shut) { body.push(line); continue }
      if (line.trim() === '---') { shut = true; continue }
      if (/^\s/.test(line)) continue
      const c = line.indexOf(':')
      if (c <= 0) continue
      const k = line.slice(0, c).trim()
      const v = line.slice(c + 1).trim()
      if (k !== '' && v !== '') data[k] = v
    }
    if (!shut) return null
    const name = unquote(data.name)
    const description = unquote(data.description)
    if (name === '' || description === '' || !NAME.test(name)) return null
    const whenRaw = data.whenToUse !== undefined ? data.whenToUse : data['when-to-use']
    const when = whenRaw === undefined ? '' : unquote(whenRaw)
    remember(name, description, when)
    return {
      name: name,
      description: description,
      whenToUse: when,
      modelInvocable: data.modelInvocable === undefined || unquote(data.modelInvocable).toLowerCase() !== 'false',
      userInvocable: data.userInvocable === undefined || unquote(data.userInvocable).toLowerCase() !== 'false',
      content: body.join('\n').trim(),
    }
  }

  const entries = async function (dir) {
    try {
      const list = await fs.listDir(dir)
      return Array.isArray(list) ? list : []
    } catch (error) {
      return []
    }
  }

  const scan = async function () {
    if (fs === undefined) return
    const root = await fs.resolve(REPO)
    const top = await entries(root)
    const files = []
    const marks = []
    for (let i = 0; i < top.length; i += 1) {
      const item = top[i]
      if (typeof item.name !== 'string' || item.target === undefined) continue
      if (item.type === 'directory') {
        const inner = await entries(item.target)
        for (let j = 0; j < inner.length; j += 1) {
          if (inner[j].type === 'file' && inner[j].name === 'SKILL.md' && inner[j].target !== undefined) {
            files.push(inner[j].target)
            marks.push(item.name + ':' + String(inner[j].version))
          }
        }
      } else if (item.type === 'file' && item.name.toLowerCase().endsWith('.md')) {
        files.push(item.target)
        marks.push(item.name + ':' + String(item.version))
      }
    }
    const next = marks.join('|')
    if (next === sig) return
    sig = next
    const built = []
    for (let i = 0; i < files.length; i += 1) {
      let raw
      try {
        raw = await fs.readText(files[i])
      } catch (error) {
        continue
      }
      const skill = parse(raw)
      if (skill === null) continue
      if (built.some(function (s) { return s.name === skill.name })) continue
      built.push(skill)
    }
    defs = built
    poke()
  }

  const ensure = function () {
    if (pending !== undefined) return pending
    pending = scan().then(function () { pending = undefined }, function () { pending = undefined })
    return pending
  }

  const snap = skills.snapshot.bind(skills)
  const get = skills.get.bind(skills)
  const kick = function () {
    if (typeof skills.invalidateCache === 'function') skills.invalidateCache()
  }

  skills.snapshot = async function (options) {
    const s = await snap(options)
    return {
      skills: (s.skills || []).filter(function (skill) { return !off.has(skill.name) }),
      complete: s.complete,
    }
  }
  skills.list = async function (options) { return (await skills.snapshot(options)).skills }
  skills.get = async function (name, options) {
    if (off.has(name)) return undefined
    return get(name, options)
  }

  ctx.effect(function () {
    return function () {
      skills.snapshot = snap
      skills.list = async function (options) { return (await snap(options)).skills }
      skills.get = get
      kick()
    }
  }, 'demo restore')

  if (fs !== undefined) {
    ctx.skills.registerProvider(function (control) {
      poke = function () { control.invalidate() }
      return {
        name: 'agents-repo',
        list: async function () {
          await ensure()
          return defs.map(function (def) {
            return {
              name: def.name,
              description: def.description,
              whenToUse: def.whenToUse,
              invocation: { modelInvocable: def.modelInvocable, userInvocable: def.userInvocable },
              source: 'user-agents',
              provider: 'agents-repo',
              rank: 450,
              locator: def.name,
              resourceBase: { kind: 'directory', path: REPO },
            }
          })
        },
        get: async function (candidate) {
          const def = defs.filter(function (s) { return s.name === candidate.name })[0]
          if (def === undefined) return undefined
          return {
            name: def.name,
            description: def.description,
            whenToUse: def.whenToUse,
            invocation: { modelInvocable: def.modelInvocable, userInvocable: def.userInvocable },
            source: 'user-agents',
            provider: 'agents-repo',
            resourceBase: { kind: 'directory', path: REPO },
            content: def.content,
          }
        },
      }
    })
    ctx.effect(function () {
      return ctx.interval(function () { ensure() }, 8000)
    }, 'demo poll')
  }

  /** Repository rows first, then whatever the live registries reported. */
  const catalog = function () {
    const out = []
    const seen = new Set()
    for (let i = 0; i < defs.length; i += 1) {
      const def = defs[i]
      seen.add(def.name)
      out.push({
        name: def.name,
        description: def.description,
        whenToUse: def.whenToUse,
        provider: 'agents-repo',
        enabled: !off.has(def.name),
      })
    }
    meta.forEach(function (info, name) {
      if (seen.has(name)) return
      out.push({
        name: str(name),
        description: str(info.description),
        whenToUse: str(info.whenToUse),
        provider: 'preset',
        enabled: !off.has(name),
      })
    })
    out.sort(function (a, b) { return a.name < b.name ? -1 : a.name > b.name ? 1 : 0 })
    return out
  }

  const flip = function (names, enabled) {
    for (let i = 0; i < names.length; i += 1) {
      const name = names[i]
      if (typeof name !== 'string' || name === '') continue
      if (enabled) off.delete(name)
      else off.add(name)
    }
    kick()
  }

  harness.handle('hub:rows', async function () {
    await ensure()
    const current = await snap({})
    const live = current.skills || []
    for (let i = 0; i < live.length; i += 1) {
      const name = str(live[i].name)
      if (name === '' || meta.has(name)) continue
      remember(name, live[i].description, live[i].whenToUse)
    }
    const rows = catalog()
    return { rows: rows, total: rows.length, offCount: off.size, repo: REPO }
  })

  harness.handle('hub:flip', async function (args) {
    const req = args === undefined ? {} : args
    flip(Array.isArray(req.names) ? req.names : [], req.enabled !== false)
    return { ok: true, offCount: off.size }
  })
}

return { inject: inject, apply: apply }

client:
'use strict'
/**
 * dsh-skill-hub — demo browser half.
 *
 * Small enough that the built payload can be read back and re-submitted
 * verbatim. Full styling and the repository diagnostics live in
 * `src/client/client.js`.
 *
 * This is the copy the running `skhub-1/pkg-2` Package was built from. Its one
 * difference from the earlier revision is visible failure handling: a rejected
 * `hub:rows` used to leave the panel stuck on the loading line forever, so it
 * now shows the message and offers a retry.
 */

const css = [
  '.hub{display:flex;flex-direction:column;gap:8px;padding:12px;font-size:13px;color:var(--dsw-alias-label-primary,#fff)}',
  '.hub-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}',
  '.hub-count{flex:1;min-width:100px;color:var(--dsw-alias-label-secondary,#aaa)}',
  '.hub-btn{padding:4px 10px;border-radius:6px;border:1px solid var(--dsw-alias-border-l1,#444);background:var(--dsw-alias-bg-layer-1,#2b2b2b);color:var(--dsw-alias-label-primary,#fff);font-size:12px;cursor:pointer}',
  '.hub-search{padding:5px 10px;border-radius:6px;border:1px solid var(--dsw-alias-border-l1,#444);background:var(--dsw-alias-bg-layer-2,#222);color:var(--dsw-alias-label-primary,#fff);font-size:12px;outline:none}',
  '.hub-list{display:flex;flex-direction:column;gap:6px;max-height:340px;overflow-y:auto}',
  '.hub-item{border:1px solid var(--dsw-alias-border-l1,#333);border-radius:8px;padding:7px 10px;background:var(--dsw-alias-bg-layer-1,#1e1e1e)}',
  '.hub-down{opacity:0.55}',
  '.hub-row{display:flex;align-items:center;gap:8px}',
  '.hub-name{font-family:monospace;font-weight:600}',
  '.hub-tag{font-size:10px;padding:1px 5px;border-radius:4px;border:1px solid var(--dsw-alias-border-l1,#444);color:var(--dsw-alias-label-secondary,#aaa)}',
  '.hub-on{color:var(--dsw-alias-state-success-primary,#22c55e);border-color:var(--dsw-alias-state-success-primary,#22c55e)}',
  '.hub-grow{flex:1}',
  '.hub-desc{margin-top:4px;color:var(--dsw-alias-label-secondary,#ccc)}',
  '.hub-note{margin-top:4px;color:var(--dsw-alias-label-tertiary,#999)}',
  '.hub-sw{position:relative;width:36px;height:20px;flex:none;border-radius:10px;border:1px solid var(--dsw-alias-border-l2,#52525b);background:var(--dsw-alias-bg-layer-2,#3f3f46);cursor:pointer;padding:0}',
  '.hub-sw-on{background:var(--dsw-alias-state-success-primary,#10b981);border-color:var(--dsw-alias-state-success-primary,#10b981)}',
  '.hub-knob{position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:7px;background:#fff;transition:transform 0.16s}',
  '.hub-sw-on .hub-knob{transform:translateX(16px)}',
].join('\n')

function Sw(props) {
  return React.createElement('button', {
    type: 'button',
    role: 'switch',
    'aria-checked': props.on,
    'aria-label': props.label,
    className: 'hub-sw' + (props.on ? ' hub-sw-on' : ''),
    onClick: function (event) { event.stopPropagation(); props.flip(!props.on) },
  }, React.createElement('span', { className: 'hub-knob' }))
}

function Hub() {
  const state = React.useState(null)
  const data = state[0]
  const setData = state[1]
  const q = React.useState('')
  const query = q[0]
  const setQuery = q[1]
  const errState = React.useState(null)
  const trouble = errState[0]
  const setTrouble = errState[1]

  const load = React.useCallback(function () {
    host.call('hub:rows', {}).then(function (result) {
      setTrouble(null)
      setData(result)
    }).catch(function (error) {
      setTrouble(String(error && error.message ? error.message : error))
    })
  }, [])

  React.useEffect(function () { load() }, [load])

  if (data === null) {
    const waiting = [React.createElement('div', { className: 'hub-count', key: 'wait' }, '正在读取技能…')]
    if (trouble !== null) {
      waiting.push(React.createElement('div', { className: 'hub-note', key: 'err' }, '读取失败：' + trouble))
      waiting.push(React.createElement('button', { type: 'button', className: 'hub-btn', key: 'retry', onClick: load }, '重试'))
    }
    return React.createElement('div', { className: 'hub' }, waiting)
  }

  const needle = query.trim().toLowerCase()
  const shown = data.rows.filter(function (row) {
    if (needle === '') return true
    if (row.name.toLowerCase().indexOf(needle) >= 0) return true
    return row.description.toLowerCase().indexOf(needle) >= 0
  })
  const names = data.rows.map(function (row) { return row.name })

  const flip = function (name, next) {
    setData(function (prev) {
      return Object.assign({}, prev, {
        rows: prev.rows.map(function (row) {
          return row.name === name ? Object.assign({}, row, { enabled: next }) : row
        }),
      })
    })
    host.call('hub:flip', { names: [name], enabled: next }).catch(function () { load() })
  }

  const flipAll = function (next) {
    setData(function (prev) {
      return Object.assign({}, prev, {
        rows: prev.rows.map(function (row) { return Object.assign({}, row, { enabled: next }) }),
      })
    })
    host.call('hub:flip', { names: names, enabled: next }).catch(function () { load() })
  }

  return React.createElement('div', { className: 'hub' },
    React.createElement('div', { className: 'hub-bar' },
      React.createElement('span', { className: 'hub-count' }, '共 ' + data.total + ' 个技能，已关闭 ' + data.offCount + ' 个'),
      React.createElement('button', { type: 'button', className: 'hub-btn', onClick: function () { flipAll(true) } }, '全部开启'),
      React.createElement('button', { type: 'button', className: 'hub-btn', onClick: function () { flipAll(false) } }, '全部关闭'),
      React.createElement('button', { type: 'button', className: 'hub-btn', onClick: load }, '刷新'),
    ),
    React.createElement('input', {
      className: 'hub-search',
      type: 'text',
      placeholder: '搜索技能名称或描述…',
      value: query,
      onChange: function (event) { setQuery(event.target.value) },
    }),
    React.createElement('div', { className: 'hub-list' },
      shown.length === 0
        ? React.createElement('div', { className: 'hub-count' }, '没有匹配的技能')
        : shown.map(function (row) {
          const box = [
            React.createElement('div', { className: 'hub-row', key: 'head' },
              React.createElement('span', { className: 'hub-name' }, row.name),
              React.createElement('span', { className: 'hub-tag' + (row.enabled ? ' hub-on' : '') }, row.enabled ? '已开启' : '已关闭'),
              React.createElement('span', { className: 'hub-tag' }, row.provider),
              React.createElement('span', { className: 'hub-grow' }),
              React.createElement(Sw, {
                on: row.enabled,
                label: row.name,
                flip: function (next) { flip(row.name, next) },
              }),
            ),
            React.createElement('div', { className: 'hub-desc', key: 'desc' }, row.description),
          ]
          if (row.whenToUse !== '') {
            box.push(React.createElement('div', { className: 'hub-note', key: 'when' }, '适用场景：' + row.whenToUse))
          }
          return React.createElement('div', {
            className: 'hub-item' + (row.enabled ? '' : ' hub-down'),
            key: row.name,
          }, box)
        }),
    ),
    React.createElement('div', { className: 'hub-note' }, '仓库：' + data.repo),
  )
}

/**
 * Register the panel in the settings navigation and in this Package's run card.
 * @param {object} ctx - the guarded Cordis context a client half receives.
 */
function apply(ctx) {
  const slots = ctx.get('slots')
  if (slots === undefined) return
  styles.insert(css)
  slots.inject('settings.section', function () {
    return slots.register({ name: 'settings.section', id: 'skills', order: 25, label: 'Skills 技能' }, function () {
      return React.createElement(Hub)
    })
  })
  slots.inject('tool.view.cordis', function () {
    return slots.register({ name: 'tool.view.cordis', key: 'self' }, function () {
      return React.createElement(Hub)
    })
  })
}

return { apply: apply }
